import{_ as c,r as t,o as i,c as r,e,a as n,s as o,d as a}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"List Controller - October CMS - 3.x","titleTemplate":false,"description":"Adds list management features to any backend page.","frontmatter":{"subtitle":"Adds list management features to any backend page."},"headers":[{"level":2,"title":"Configuring the List Behavior","slug":"configuring-the-list-behavior","link":"#configuring-the-list-behavior","children":[{"level":3,"title":"Adding a Toolbar","slug":"adding-a-toolbar","link":"#adding-a-toolbar","children":[]},{"level":3,"title":"Filtering the List","slug":"filtering-the-list","link":"#filtering-the-list","children":[]}]},{"level":2,"title":"Defining List Columns","slug":"defining-list-columns","link":"#defining-list-columns","children":[]},{"level":2,"title":"Displaying the List","slug":"displaying-the-list","link":"#displaying-the-list","children":[]},{"level":2,"title":"Multiple List Definitions","slug":"multiple-list-definitions","link":"#multiple-list-definitions","children":[]},{"level":2,"title":"Extending List Behavior","slug":"extending-list-behavior","link":"#extending-list-behavior","children":[{"level":3,"title":"Extending the List Configuration","slug":"extending-the-list-configuration","link":"#extending-the-list-configuration","children":[]},{"level":3,"title":"Overriding Controller Action","slug":"overriding-controller-action","link":"#overriding-controller-action","children":[]},{"level":3,"title":"Overriding Views","slug":"overriding-views","link":"#overriding-views","children":[]},{"level":3,"title":"Extending Column Definitions","slug":"extending-column-definitions","link":"#extending-column-definitions","children":[]},{"level":3,"title":"Inject CSS Row Class","slug":"inject-css-row-class","link":"#inject-css-row-class","children":[]},{"level":3,"title":"Overriding Column URL","slug":"overriding-column-url","link":"#overriding-column-url","children":[]},{"level":3,"title":"Extending Filter Scopes","slug":"extending-filter-scopes","link":"#extending-filter-scopes","children":[{"level":4,"title":"Extending the Filter Response","slug":"extending-the-filter-response","link":"#extending-the-filter-response","children":[]}]},{"level":3,"title":"Extending the Model Query","slug":"extending-the-model-query","link":"#extending-the-model-query","children":[]},{"level":3,"title":"Extending the Records Collection","slug":"extending-the-records-collection","link":"#extending-the-records-collection","children":[]},{"level":3,"title":"Custom Column Types","slug":"custom-column-types","link":"#custom-column-types","children":[]}]}],"relativePath":"3.x/extend/lists/list-controller.md","filePath":"3.x/extend/lists/list-controller.md"}'),u={name:"3.x/extend/lists/list-controller.md"};function d(k,s,g,h,m,f){const p=t("pre-heading"),l=t("post-heading");return i(),r("div",null,[e(p),s[0]||(s[0]=n("h1",null,"List Controller",-1)),e(l),s[1]||(s[1]=o(`<p>The <code>Backend\\Behaviors\\ListController</code> class is a controller behavior used for easily adding a record list to a page. The behavior provides the sortable and searchable list with optional links on its records. The behavior provides the controller action <code>index</code> however the list can be rendered anywhere and multiple list definitions can be used.</p><p>List behavior depends on list <a href="./../../element/list-columns.html">column definitions</a> and a <a href="./../database/model.html">model class</a>. In order to use the list behavior you should add it to the <code>$implement</code> property of the controller class. Also, the <code>$listConfig</code> class property should be defined and its value should refer to the YAML file used for configuring the behavior properties.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ListController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$listConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_list.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Very often the list and <a href="./../forms/form-controller.html">form controller</a> are used together in a same controller.</p></div><h2 id="configuring-the-list-behavior"><a href="#configuring-the-list-behavior" class="header-anchor">#</a> Configuring the List Behavior</h2><p>The configuration file referred in the <code>$listConfig</code> property is defined in YAML format. The file should be placed into the controller&#39;s <a href="./../system/controllers.html">views directory</a>. Below is an example of a typical list behavior configuration file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">title</span><span class="token punctuation">:</span> Blog Posts
<span class="token key atrule">list</span><span class="token punctuation">:</span> ~/plugins/acme/blog/models/post/columns.yaml
<span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Blog\\Models\\Post
<span class="token key atrule">recordUrl</span><span class="token punctuation">:</span> acme/blog/posts/update/<span class="token punctuation">:</span>id
</code></pre></div><p>The following properties are required in the list configuration file.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a title for this list.</td></tr><tr><td><strong>list</strong></td><td>a configuration array or reference to a list column definition file, see <a href="./../../element/list-columns.html">list columns</a>.</td></tr><tr><td><strong>modelClass</strong></td><td>a model class name, the list data is loaded from this model.</td></tr></tbody></table></div><p>The configuration properties listed below are optional.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>filter</strong></td><td>filter configuration, see <a href="./filters.html">list filters</a>.</td></tr><tr><td><strong>recordUrl</strong></td><td>link each list record to another page. Eg: <strong>users/update:id</strong>. The <code>:id</code> part is replaced with the record identifier. This allows you to link the list behavior and the <a href="./../forms/form-controller.html">form behavior</a>.</td></tr><tr><td><strong>recordOnClick</strong></td><td>custom JavaScript code to execute when clicking on a record.</td></tr><tr><td><strong>noRecordsMessage</strong></td><td>a message to display when no records are found, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>deleteMessage</strong></td><td>a message to display when records are bulk deleted, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>noRecordsDeletedMessage</strong></td><td>a message to display when a bulk delete action is triggered, but no records were deleted, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>records to display per page, use 0 for no pages. Default: <code>0</code></td></tr><tr><td><strong>perPageOptions</strong></td><td>options for number of items per page. Default: <code>[20, 40, 80, 100, 120]</code></td></tr><tr><td><strong>showPageNumbers</strong></td><td>displays page numbers with pagination. Disable this to improve list performance when working with large tables. Default: <code>true</code></td></tr><tr><td><strong>toolbar</strong></td><td>reference to a Toolbar Widget configuration file, or an array with configuration (see below).</td></tr><tr><td><strong>showSorting</strong></td><td>displays the sorting link on each column. Default: <code>true</code></td></tr><tr><td><strong>defaultSort</strong></td><td>sets a default sorting column and direction when user preference is not defined. Supports a string or an array with keys <code>column</code> and <code>direction</code>. The direction can be <code>asc</code> for ascending (default) or <code>desc</code> for descending order.</td></tr><tr><td><strong>showCheckboxes</strong></td><td>displays checkboxes next to each record. Default: <code>false</code>.</td></tr><tr><td><strong>showSetup</strong></td><td>displays the list column set up button. Default: <code>false</code>.</td></tr><tr><td><strong>structure</strong></td><td>enables a structured list, see the <a href="./structures.html">sorting records article</a> for more details.</td></tr><tr><td><strong>customViewPath</strong></td><td>specify a custom view path to override partials used by the list, optional.</td></tr><tr><td><strong>customPageName</strong></td><td>specify a custom variable name to use in the page URL for paginated records. Set to <code>false</code> to disable storing the page number in the URL. Default: <code>page</code>.</td></tr></tbody></table></div><h3 id="adding-a-toolbar"><a href="#adding-a-toolbar" class="header-anchor">#</a> Adding a Toolbar</h3><p>To include a toolbar with the list, add the following configuration to the list configuration YAML file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">toolbar</span><span class="token punctuation">:</span>
    <span class="token key atrule">buttons</span><span class="token punctuation">:</span> list_toolbar
    <span class="token key atrule">search</span><span class="token punctuation">:</span>
        <span class="token key atrule">prompt</span><span class="token punctuation">:</span> Find records
</code></pre></div><p>The toolbar configuration allows:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>buttons</strong></td><td>a reference to a controller partial file with the toolbar buttons. Eg: <strong>_list_toolbar.htm</strong></td></tr><tr><td><strong>search</strong></td><td>reference to a Search Widget configuration file, or an array with configuration.</td></tr></tbody></table></div><p>The search configuration supports the following properties:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>prompt</strong></td><td>a placeholder to display when there is no active search, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>mode</strong></td><td>defines the search strategy to either contain all words, any word or exact phrase. Supported options: <code>all</code>, <code>any</code>, <code>exact</code>. Default: <code>all</code>.</td></tr><tr><td><strong>scope</strong></td><td>specifies a <a href="./../database/model.html">model query scope</a> method defined in the <strong>list model</strong> to apply to the search query. The first argument will contain the query object (as per a regular scope method), the second will contain the search term, and the third will be an array of the columns to be searched.</td></tr><tr><td><strong>searchOnEnter</strong></td><td>setting this to true will make the search widget wait for the Enter key to be pressed before it starts searching (the default behavior is that it starts searching automatically after someone enters something into the search field and then pauses for a short moment). Default: <code>false</code>.</td></tr></tbody></table></div>`,18)),s[2]||(s[2]=n("p",null,[a("The toolbar buttons partial referred above should contain the toolbar control definition with some buttons. The partial could also contain a "),n("a",{href:"https://octobercms.com/docs/ui/scoreboard",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("scoreboard control"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(" with charts. Example of a toolbar partial with the "),n("strong",null,"New Post"),a(" button referring to the "),n("strong",null,"create"),a(" action provided by the "),n("a",{href:"./forms.html"},"form behavior"),a(":")],-1)),s[3]||(s[3]=o(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>toolbar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts/create&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary oc-icon-plus<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        New Post
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>When using list checkboxes, you may toggle a button&#39;s enabled state with the <code>data-list-checked-trigger</code> attribute.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">&lt;</span>button
    type<span class="token operator">=</span><span class="token string double-quoted-string">&quot;button&quot;</span>
    <span class="token keyword">class</span><span class="token operator">=</span><span class="token string double-quoted-string">&quot;btn btn-primary&quot;</span>
    data<span class="token operator">-</span><span class="token keyword">list</span><span class="token operator">-</span>checked<span class="token operator">-</span>trigger<span class="token operator">&gt;</span>
    Delete Selected
<span class="token operator">&lt;</span><span class="token operator">/</span>button<span class="token operator">&gt;</span>
</code></pre></div><p>You may also pass the checked values to an AJAX request using the <code>data-list-checked-request</code> attribute.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">&lt;</span>button
    type<span class="token operator">=</span><span class="token string double-quoted-string">&quot;button&quot;</span>
    <span class="token keyword">class</span><span class="token operator">=</span><span class="token string double-quoted-string">&quot;btn btn-primary&quot;</span>
    data<span class="token operator">-</span>request<span class="token operator">=</span><span class="token string double-quoted-string">&quot;onDelete&quot;</span>
    data<span class="token operator">-</span><span class="token keyword">list</span><span class="token operator">-</span>checked<span class="token operator">-</span>request<span class="token operator">&gt;</span>
    Delete Selected
<span class="token operator">&lt;</span><span class="token operator">/</span>button<span class="token operator">&gt;</span>
</code></pre></div><h3 id="filtering-the-list"><a href="#filtering-the-list" class="header-anchor">#</a> Filtering the List</h3><p>To filter a list by user defined input, add the following list configuration to the YAML file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">filter</span><span class="token punctuation">:</span> $/acme/blog/models/post/scopes.yaml
</code></pre></div><p>The <strong>filter</strong> property should make reference to a <a href="./filters.html">filter configuration file</a> path or supply an array with the configuration.</p><h2 id="defining-list-columns"><a href="#defining-list-columns" class="header-anchor">#</a> Defining List Columns</h2><div class="custom-block aside"><p>The available list column properties can be found on the <a href="./../../element/list-columns.html">list column definitions</a> page.</p></div><p>List columns are defined with the YAML file. The column configuration is used by the list behavior for creating the record table and displaying model columns in the table cells. The file is placed to a subdirectory of the <strong>models</strong> directory of a plugin. The subdirectory name matches the model class name written in lowercase. The file name doesn&#39;t matter, but the <strong>columns.yaml</strong> and <strong>list_columns.yaml</strong> are common names. Example list columns file location:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           └── <code>models</code>
|               ├── post  <em>← Config Directory</em>
|               |   └── columns.yaml  <em>← Config File</em>
|               └── Post.php  <em>← Model Class</em></p>
</code></pre><p>The next example shows the typical contents of a list column definitions file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># columns.yaml</span>
<span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Name
    <span class="token key atrule">email</span><span class="token punctuation">:</span> Email
</code></pre></div><h2 id="displaying-the-list"><a href="#displaying-the-list" class="header-anchor">#</a> Displaying the List</h2><p>Usually lists are displayed in the <a href="./../system/views.html">index view</a> file. Since lists include the toolbar, the view file will consist solely of the single <code>listRender</code> method call.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">listRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="multiple-list-definitions"><a href="#multiple-list-definitions" class="header-anchor">#</a> Multiple List Definitions</h2><p>The list behavior can support multiple lists in the same controller using named definitions. The <code>$listConfig</code> property can be defined as an array where the key is a definition name and the value is the configuration file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$listConfig</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;templates&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_templates_list.yaml&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;layouts&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_layouts_list.yaml&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Each definition can then be displayed by passing the definition name as the first argument when calling the <code>listRender</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">listRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;templates&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="extending-list-behavior"><a href="#extending-list-behavior" class="header-anchor">#</a> Extending List Behavior</h2><p>Sometimes you may wish to modify the default list behavior and there are several ways you can do this.</p><h3 id="extending-the-list-configuration"><a href="#extending-the-list-configuration" class="header-anchor">#</a> Extending the List Configuration</h3><p>You may extend the list configuration dynamically using the <code>listGetConfig</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listGetConfig</span><span class="token punctuation">(</span><span class="token variable">$definition</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$config</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ListController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">listGetConfig</span><span class="token punctuation">(</span><span class="token variable">$definition</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Implement structure dynamically</span>
    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">structure</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;showTree&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$config</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="overriding-controller-action"><a href="#overriding-controller-action" class="header-anchor">#</a> Overriding Controller Action</h3><p>You may use your own logic for the <code>index</code> action method in the controller, then optionally call the List behavior <code>index</code> parent method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">//</span>
    <span class="token comment">// Do any custom code here</span>
    <span class="token comment">//</span>

    <span class="token comment">// Call the ListController behavior index() method</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ListController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="overriding-views"><a href="#overriding-views" class="header-anchor">#</a> Overriding Views</h3><p>The <code>ListController</code> behavior has a main container view that you may override by creating a special file named <code>_list_container.php</code> in your controller directory. The following example will add a sidebar to the list:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$toolbar</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$toolbar</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>row row-flush<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-sm-3<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        [Insert sidebar here]
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-sm-9 list-with-sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The behavior will invoke a <code>Lists</code> widget that also contains numerous views that you may override. This is possible by specifying a <code>customViewPath</code> property as described in the list configuration options. The widget will look in this path for a view first, then fall back to the default location.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># Custom view path</span>
<span class="token key atrule">customViewPath</span><span class="token punctuation">:</span> $/acme/blog/controllers/reviews/list
</code></pre></div><div class="custom-block tip"><p>It is a good idea to use a sub-directory, for example called <code>list</code>, to avoid conflicts.</p></div><p>For example, to modify the list body row markup, create a file called <code>list/_list_body_row.php</code> in your controller directory.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>tr</span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$columns</span> <span class="token keyword">as</span> <span class="token variable">$key</span> <span class="token operator">=&gt;</span> <span class="token variable">$column</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>td</span><span class="token punctuation">&gt;</span></span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getColumnValue</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$column</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>td</span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endforeach</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>tr</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="extending-column-definitions"><a href="#extending-column-definitions" class="header-anchor">#</a> Extending Column Definitions</h3><p>You may extend the columns of another controller from outside by binding to the <code>backend.list.extendColumns</code> <a href="./../services/event.html">global event</a>. The event function will take a <code>$list</code> argument that represents the <code>Backend\\Widgets\\Lists</code> object, where you can use the <code>getController</code> and <code>getModel</code> methods to check the execution context.</p><p>Since this event has the potential to affect all lists, it is essential to check that the controller and model is of the correct type. Here is an example using the <code>addColumns</code> method to add new columns to the event log list, and modify an existing column.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.list.extendColumns&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$list</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>
        <span class="token operator">!</span><span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>EventLogs</span> <span class="token operator">||</span>
        <span class="token operator">!</span><span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>EventLog</span>
    <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add a new column</span>
    <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">addColumns</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;my_column&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Column&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Modify an existing column</span>
    <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">useConfig</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;path&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;column_title&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also extend the list columns internally by overriding the <code>listExtendColumns</code> method inside the controller class. This will only affect the list used by the <code>ListController</code> behavior.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ListController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendColumns</span><span class="token punctuation">(</span><span class="token variable">$list</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">addColumns</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">getColumn</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The following methods are available on the <code>$list</code> object.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>addColumns</strong></td><td>adds new columns to the list</td></tr><tr><td><strong>removeColumn</strong></td><td>removes a column from the list</td></tr><tr><td><strong>getColumn</strong></td><td>returns an existing column definition</td></tr></tbody></table></div><p>Each method takes an array of columns similar to the <a href="./../../element/list-columns.html">list column configuration</a>.</p><h3 id="inject-css-row-class"><a href="#inject-css-row-class" class="header-anchor">#</a> Inject CSS Row Class</h3><p>You may inject a custom css row class by adding a <code>listInjectRowClass</code> method on the controller class. This method can take two arguments, <strong>$record</strong> will represent a single model record and <strong>$definition</strong> contains the name of the List widget definition. You may return any string value containing your row classes. These classes will be added to the row&#39;s HTML markup.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Lessons</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listInjectRowClass</span><span class="token punctuation">(</span><span class="token variable">$lesson</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// Strike through past lessons</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$lesson</span><span class="token operator">-&gt;</span><span class="token property">lesson_date</span><span class="token operator">-&gt;</span><span class="token function">lt</span><span class="token punctuation">(</span><span class="token class-name static-context">Carbon</span><span class="token operator">::</span><span class="token function">today</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;strike&#39;</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>A special CSS class <code>nolink</code> is available to force a row to be unclickable, even if the <code>recordUrl</code> or <code>recordOnClick</code> properties are defined for the list widget. Returning this class in an event will allow you to make records unclickable - for example, for soft-deleted rows or for informational rows:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listInjectRowClass</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token function">trashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;nolink&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="overriding-column-url"><a href="#overriding-column-url" class="header-anchor">#</a> Overriding Column URL</h3><p>You may specify the click action for a column record by overriding the <code>listOverrideRecordUrl</code> method. This method can return a string for a new backend URL or an array with a complex definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listOverrideRecordUrl</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;acme/test/services/preview/<span class="token interpolation"><span class="token punctuation">{</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">}</span></span>&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To override the onclick behavior return an array with the <code>onclick</code> key and change the <code>url</code> to null.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listOverrideRecordUrl</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_banned</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;onclick&#39;</span> <span class="token operator">=&gt;</span> <span class="token string double-quoted-string">&quot;alert(&#39;Unable to click&#39;)&quot;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant">null</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To make a column unclickable entirely return an array with the <code>clickable</code> key set to false.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listOverrideRecordUrl</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_disabled</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;clickable&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-filter-scopes"><a href="#extending-filter-scopes" class="header-anchor">#</a> Extending Filter Scopes</h3><p>You may extend the filter scopes of another controller by binding to the <code>backend.filter.extendScopes</code> <a href="./../services/event.html">global event</a>. This method can take the argument <code>$filter</code> which will represent the <code>Backend\\Widgets\\Filter</code> object, where you can use the <code>getController</code>, <code>getModel</code> and <code>getContext</code> methods to check the execution context.</p><p>Since this event has the potential to affect all filters, it is essential to check that the controller and model is of the correct type. Here is an example using the <code>addScopes</code> method to add new fields to the event log list, and adjust the CSS classes.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.filter.extendScopes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>
        <span class="token operator">!</span><span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>EventLogs</span> <span class="token operator">||</span>
        <span class="token operator">!</span><span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">getModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>EventLog</span>
    <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add a new scope</span>
    <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">addScopes</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;my_scope&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Filter Scope&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Add custom CSS classes to the filter widget</span>
    <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token property">cssClasses</span> <span class="token operator">=</span> <span class="token function">array_merge</span><span class="token punctuation">(</span>
        <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token property">cssClasses</span><span class="token punctuation">,</span>
        <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;my-array&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;of-classes&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also extend the filter scopes internally to the controller class, simply override the <code>listFilterExtendScopes</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ListController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listFilterExtendScopes</span><span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">addScopes</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The following methods are available on the <code>$filter</code> object. The scopes available are the same as the <a href="./filters.html">list filters configuration</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>addScopes</strong></td><td>adds new scopes to filter widget using <a href="./filters.html">list filters configuration</a></td></tr><tr><td><strong>removeScope</strong></td><td>remove scope from filter widget</td></tr><tr><td><strong>getScope</strong></td><td>returns an existing scope definition</td></tr></tbody></table></div><h4 id="extending-the-filter-response"><a href="#extending-the-filter-response" class="header-anchor">#</a> Extending the Filter Response</h4><p>The <code>listExtendRefreshResults</code> method can interact with the AJAX update response when the list updates, and should return an array of additional partial updates. The <code>listGetFilterWidget</code> will return the filter widget for access to the scopes.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendRefreshResults</span><span class="token punctuation">(</span><span class="token variable">$filter</span><span class="token punctuation">,</span> <span class="token variable">$result</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$statusCode</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">listGetFilterWidget</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getScope</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status_code&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#my-partial-id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-the-model-query"><a href="#extending-the-model-query" class="header-anchor">#</a> Extending the Model Query</h3><p>The lookup query for the list <a href="./../database/model.html">database model</a> can be extended by overriding the <code>listExtendQuery</code> method inside the controller class. This example will ensure that soft deleted records are included in the list data, by applying the <strong>withTrashed</strong> scope to the query.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>When dealing with multiple lists definitions in a same controller, you can use the second parameter of <code>listExtendQuery</code> which contains the name of the definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$listConfig</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;inbox&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_inbox_list.yaml&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;trashed&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;config_trashed_list.yaml&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$definition</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$definition</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;trashed&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">onlyTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may also join other tables to aid with searching and sorting. The following will join the <code>post_statuses</code> table and introduce the <code>status_sort_order</code> and <code>status_name</code> columns to the query.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$definition</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_statuses&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts.status_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;post_statuses.id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">addSelect</span><span class="token punctuation">(</span>
        <span class="token string single-quoted-string">&#39;post_statuses.sort_order as status_sort_order&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;post_statuses.name as status_name&#39;</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <a href="./filters.html">list filter</a> model query can also be extended by overriding the <code>listFilterExtendQuery</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listFilterExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">scopeName</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&lt;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;all&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-the-records-collection"><a href="#extending-the-records-collection" class="header-anchor">#</a> Extending the Records Collection</h3><p>The collection of records used by the list can be extended by overriding the <code>listExtendRecords</code> method inside the controller class. This example uses the <code>sort</code> method on the <a href="./../database/collection.html">record collection</a> to change the sort order of the records.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listExtendRecords</span><span class="token punctuation">(</span><span class="token variable">$records</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$a</span><span class="token punctuation">,</span> <span class="token variable">$b</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$a</span><span class="token operator">-&gt;</span><span class="token function">computedVal</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token variable">$b</span><span class="token operator">-&gt;</span><span class="token function">computedVal</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="custom-column-types"><a href="#custom-column-types" class="header-anchor">#</a> Custom Column Types</h3><p>Custom list column types can be registered in the back-end with the <code>registerListColumnTypes</code> method of the <a href="./../extending.html">plugin registration file</a>. The method should return an array where the key is the type name and the value is a callable function. The callable function receives three arguments, the native <code>$value</code>, the <code>$column</code> definition object and the model <code>$record</code> object.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerListColumnTypes</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// A local method, i.e $this-&gt;evalUppercaseListColumn()</span>
        <span class="token string single-quoted-string">&#39;uppercase&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;evalUppercaseListColumn&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

        <span class="token comment">// Using an inline closure</span>
        <span class="token string single-quoted-string">&#39;loveit&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string double-quoted-string">&quot;I love <span class="token interpolation"><span class="token punctuation">{</span><span class="token variable">$value</span><span class="token punctuation">}</span></span>&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">evalUppercaseListColumn</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$column</span><span class="token punctuation">,</span> <span class="token variable">$record</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Using the custom list column type is as simple as calling it by name using the <code>type</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># columns.yaml</span>
<span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">secret_code</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Secret code
        <span class="token key atrule">type</span><span class="token punctuation">:</span> uppercase
</code></pre></div>`,88))])}const v=c(u,[["render",d]]);export{b as __pageData,v as default};
